"""Shared Spanish -> English translation pipeline (CS6140 HW6 Problem 4; HW7 Problems 3-4).

HW6 and HW7 import this file unchanged, so every translation model in the course is trained on the same
pairs, uses the same vocabularies and is scored on the same test sentences with the same BLEU.

Data. Tatoeba sentence pairs (https://tatoeba.org, CC BY 2.0 FR), the course file
`data/sentence_pairs_large.tsv` (columns: id, Spanish, id, English). Text is lower-cased and
punctuation (including the Spanish marks the d2l book's French-English code does not know) becomes
separate tokens. Only pairs whose two sides both have at most `max_len` tokens are kept.

Splits are made by *Spanish sentence*, not by pair: a Spanish sentence with several English
translations goes entirely into one split. So a test sentence was never seen in training, and all its
translations serve as references for BLEU. The final-test split is never scored in HW6 or HW7; it is kept
untouched for a last comparison.

The data module subclasses the book's `d2l.MTFraEng` (d2l §10.5) and returns its batch format:
(src, tgt_input, src_valid_len, label), with src = tokens + <eos> + padding, tgt_input = <bos> + tokens,
label = tokens + <eos> (both padded), all of length num_steps = max_len + 1.

Models follow the book's encoder-decoder interface (d2l §10.6): `model(src, tgt_input, src_valid_len)`
returns logits (batch, steps, vocab); `model.encoder(src, src_valid_len)` and
`model.decoder.init_state(enc_outputs, src_valid_len)` / `model.decoder(Y, state)` decode step by step
(this is what `d2l.EncoderDecoder.predict_step` and `translate_greedy` below call).

Answer-only code. Blocks between `# --- SOLUTION-ONLY (begin)` and `# --- SOLUTION-ONLY (end)` contain the
answers to HW6 TODO blanks (masked loss, greedy decoding, the clipped n-gram count, BLEU by length). They are
stripped from the copy shipped with the HW6 starter; there the notebook passes its own functions in
(`loss_fn=`, `clip_fn=`, `bleu_by_len=`). HW7 ships the full module.

BLEU is the standard corpus BLEU-4 (Papineni et al., 2002), as reported by sacrebleu: clipped n-gram counts
over the whole test set, all references per sentence, brevity penalty against the closest reference
length, x100. (The book's `d2l.bleu` is a different, sentence-level variant; its numbers are not
comparable.)
"""
import collections
import json
import math
import os
import random
import re
import time

import torch
from torch import nn
import torch.nn.functional as F
from d2l import torch as d2l

BUCKETS = ((1, 4), (5, 6), (7, 8), (9, 12))     # Spanish sentence length (tokens) for BLEU by length


def tokenize(sentence):
    """Lower-case words (with accents and inner apostrophes) and punctuation, each a token."""
    sentence = sentence.lower().replace(" ", " ").replace("\xa0", " ").replace("’", "'")
    return re.findall(r"[\w']+|[.,!?¿¡;:\"]", sentence)


class TatoebaEsEn(d2l.MTFraEng):
    """Spanish -> English Tatoeba pairs as a d2l data module (see the module docstring)."""

    def __init__(self, root, batch_size=128, max_len=12, num_train=100_000, num_val=1_000, num_test=2_000,
                 num_final_test=2_000, min_freq=2, seed=0):
        d2l.DataModule.__init__(self)
        self.save_hyperparameters()
        self.num_steps = max_len + 1
        src, tgt = self._tokenize(self._preprocess(self._download()))
        by_src = collections.defaultdict(list)
        for es, en in zip(src, tgt):
            by_src[tuple(es)].append(en)
        sources = list(by_src)
        rng = random.Random(seed)
        rng.shuffle(sources)
        cut = [num_test, num_test + num_final_test, num_test + num_final_test + num_val]
        test, final, val, train = sources[:cut[0]], sources[cut[0]:cut[1]], sources[cut[1]:cut[2]], sources[cut[2]:]
        train_pairs = [(list(es), en) for es in train for en in by_src[es]]
        rng.shuffle(train_pairs)
        self.num_available = len(train_pairs)
        train_pairs = train_pairs[:num_train]
        self.arrays, self.src_vocab, self.tgt_vocab = self._build_arrays(*zip(*train_pairs))
        val_pairs = [(list(es), en) for es in val for en in by_src[es]]
        self.val_arrays = self._build_arrays(*zip(*val_pairs), self.src_vocab, self.tgt_vocab)[0]
        strip = lambda s: [w for w in s if w != "<eos>"]
        self.test_src = [strip(es) for es in test]
        self.test_refs = [[strip(en) for en in by_src[es]] for es in test]
        self.final_test_src = [strip(es) for es in final]
        self.final_test_refs = [[strip(en) for en in by_src[es]] for es in final]
        self.num_pairs, self.num_sources = len(src), len(sources)

    def _download(self):
        path = os.path.join(self.root, "sentence_pairs_large.tsv")
        lines = []
        with open(path, encoding="utf-8-sig") as f:
            for line in f:
                parts = line.rstrip("\n").split("\t")
                if len(parts) >= 4:
                    lines.append(parts[1].replace("\t", " ") + "\t" + parts[3].replace("\t", " "))
        return "\n".join(lines)

    def _preprocess(self, text):
        return text                                 # tokenize() does the lower-casing and splitting

    def _tokenize(self, text, max_examples=None):
        """(src, tgt) token lists, each ending in '<eos>'; pairs longer than max_len on either side dropped."""
        src, tgt = [], []
        for line in text.split("\n"):
            es, en = (tokenize(part) for part in line.split("\t"))
            if 0 < len(es) <= self.max_len and 0 < len(en) <= self.max_len:
                src.append(es + ["<eos>"])
                tgt.append(en + ["<eos>"])
        return src, tgt

    def _build_arrays(self, src, tgt, src_vocab=None, tgt_vocab=None):
        """The book's _build_arrays, but on token lists, with the vocabularies built from training data only."""
        def _build_array(sentences, vocab, is_tgt=False):
            pad_or_trim = lambda seq, t: seq[:t] if len(seq) > t else seq + ["<pad>"] * (t - len(seq))
            sentences = [pad_or_trim(list(s), self.num_steps) for s in sentences]
            if is_tgt:
                sentences = [["<bos>"] + s for s in sentences]
            if vocab is None:
                vocab = d2l.Vocab(sentences, min_freq=self.min_freq, reserved_tokens=["<pad>", "<bos>", "<eos>"])
            array = torch.tensor([vocab[s] for s in sentences])
            valid_len = (array != vocab["<pad>"]).type(torch.int32).sum(1)
            return array, vocab, valid_len
        src_array, src_vocab, src_valid_len = _build_array(src, src_vocab)
        tgt_array, tgt_vocab, _ = _build_array(tgt, tgt_vocab, True)
        return (src_array, tgt_array[:, :-1], src_valid_len, tgt_array[:, 1:]), src_vocab, tgt_vocab

    def get_dataloader(self, train):
        return self.get_tensorloader(self.arrays if train else self.val_arrays, train)

    def src_batch(self, sentences):
        """Token lists (no <eos>) -> (src, src_valid_len) tensors in the training format."""
        rows = [list(s)[:self.max_len] + ["<eos>"] for s in sentences]
        rows = [r + ["<pad>"] * (self.num_steps - len(r)) for r in rows]
        arr = torch.tensor([self.src_vocab[r] for r in rows])
        valid_len = (arr != self.src_vocab["<pad>"]).type(torch.int32).sum(1)
        return arr, valid_len

    def describe(self):
        n = len(self.arrays[0])
        return (f"Tatoeba es->en, both sides <= {self.max_len} tokens: {self.num_pairs:,} pairs, "
                f"{self.num_sources:,} distinct Spanish sentences.\n"
                f"train {n:,} pairs (of {self.num_available:,} available) | val {len(self.val_arrays[0]):,} pairs | "
                f"test {len(self.test_src):,} Spanish sentences "
                f"({sum(map(len, self.test_refs)) / len(self.test_refs):.2f} references each) | "
                f"final test {len(self.final_test_src):,} (kept untouched)\n"
                f"vocabularies: Spanish {len(self.src_vocab):,}, English {len(self.tgt_vocab):,} tokens "
                f"(min frequency {self.min_freq}); num_steps = {self.num_steps}")


# ------------------------------------------------------------------------------------------------
# The book's RNN decoder (d2l §10.7) -- the d2l *package* ships the encoder and d2l.Seq2Seq but not this
# class, nor the masked loss. Copied from the book (CC BY-SA 4.0), with nn.LazyLinear -> nn.Linear.
# ------------------------------------------------------------------------------------------------
class Seq2SeqDecoder(d2l.Decoder):
    """The book's RNN decoder: the encoder's last-step output is the context at every step."""

    def __init__(self, vocab_size, embed_size, num_hiddens, num_layers, dropout=0):
        super().__init__()
        self.embedding = nn.Embedding(vocab_size, embed_size)
        self.rnn = d2l.GRU(embed_size + num_hiddens, num_hiddens, num_layers, dropout)
        self.dense = nn.Linear(num_hiddens, vocab_size)
        self.apply(d2l.init_seq2seq)

    def init_state(self, enc_all_outputs, *args):
        return enc_all_outputs

    def forward(self, X, state):
        embs = self.embedding(X.t().type(torch.int32))         # (num_steps, batch, embed)
        enc_output, hidden_state = state
        context = enc_output[-1]                                # the encoder's output at its LAST position
        context = context.repeat(embs.shape[0], 1, 1)
        embs_and_context = torch.cat((embs, context), -1)
        outputs, hidden_state = self.rnn(embs_and_context, hidden_state)
        outputs = self.dense(outputs).swapaxes(0, 1)            # (batch, num_steps, vocab)
        return outputs, [enc_output, hidden_state]


class BookSeq2Seq(d2l.Seq2Seq):
    """d2l.Seq2Seq plus the book's masked loss (padding positions do not count)."""

    def loss(self, Y_hat, Y):
        l = d2l.Classifier.loss(self, Y_hat, Y, averaged=False)
        mask = (Y.reshape(-1) != self.tgt_pad).type(torch.float32)
        return (l * mask).sum() / mask.sum()


def book_seq2seq(data, embed_size=256, num_hiddens=512, num_layers=2, dropout=0.2, lr=1e-3):
    """The book's package baseline: d2l.Seq2SeqEncoder + the book's decoder, wrapped in d2l.Seq2Seq."""
    encoder = d2l.Seq2SeqEncoder(len(data.src_vocab), embed_size, num_hiddens, num_layers, dropout)
    decoder = Seq2SeqDecoder(len(data.tgt_vocab), embed_size, num_hiddens, num_layers, dropout)
    return BookSeq2Seq(encoder, decoder, tgt_pad=data.tgt_vocab["<pad>"], lr=lr)


def packed_rnn(rnn, embs, valid_len):
    """Run a time-major nn.GRU / nn.LSTM over padded input, *skipping the padding*.

    embs: (num_steps, batch, embed); valid_len: (batch,). Returns outputs (num_steps, batch, hidden), zero
    at padded positions, and the final state taken at each sentence's own last token (not after the padding)."""
    packed = nn.utils.rnn.pack_padded_sequence(embs, valid_len.cpu(), enforce_sorted=False)
    outputs, state = rnn(packed)
    outputs, _ = nn.utils.rnn.pad_packed_sequence(outputs, total_length=embs.shape[0])
    return outputs, state


