# Training (provided plumbing)
# ------------------------------------------------------------------------------------------------


@torch.no_grad()
def eval_loss(model, data, device, loss_fn, batch_size=512):
    model.eval()
    tot, n = 0.0, 0
    pad = data.tgt_vocab["<pad>"]
    arrays = data.val_arrays
    for i in range(0, len(arrays[0]), batch_size):
        src, tgt_in, src_len, label = (a[i:i + batch_size].to(device) for a in arrays)
        k = (label != pad).sum().item()               # loss_fn averages over real tokens: weight by their count
        tot += loss_fn(model(src, tgt_in, src_len), label).item() * k
        n += k
    model.train()
    return tot / n


def train_seq2seq(model, data, device, steps, loss_fn=None, lr=1e-3, clip=1.0, progress=None, desc="seq2seq",
                  seed=0):
    """AdamW on random training batches + gradient clipping; returns a history dict.
    Every run with the same seed sees the same sequence of batches."""
    pad = data.tgt_vocab["<pad>"]
    if loss_fn is None:                    # (masked_loss is not in the HW6 student copy: pass loss_fn there)
        loss_fn = lambda logits, labels: masked_loss(logits, labels, pad)
    model.to(device).train()
    opt = torch.optim.AdamW(model.parameters(), lr=lr)
    g = torch.Generator().manual_seed(seed)
    n = len(data.arrays[0])
    eval_every = max(steps // 10, 1)
    hist = {"step": [], "train_loss": [], "val_loss": []}
    bar = progress(steps, desc) if progress else None
    running = None
    t0 = time.time()
    for step in range(1, steps + 1):
        idx = torch.randint(n, (data.batch_size,), generator=g)
        src, tgt_in, src_len, label = (a[idx].to(device) for a in data.arrays)
        loss = loss_fn(model(src, tgt_in, src_len), label)
        opt.zero_grad()
        loss.backward()
        if clip:
            nn.utils.clip_grad_norm_(model.parameters(), clip)
        opt.step()
        running = loss.item() if running is None else 0.98 * running + 0.02 * loss.item()
        if bar is not None:
            bar.update(1)
        if step % eval_every == 0 or step == steps:
            hist["step"].append(step)
            hist["train_loss"].append(running)
            hist["val_loss"].append(eval_loss(model, data, device, loss_fn))
            if bar is not None:
                bar.set_postfix(val_loss=f"{hist['val_loss'][-1]:.3f}")
    if bar is not None:
        bar.close()
    hist["seconds"] = time.time() - t0
    hist["steps"] = steps
    return hist


# ------------------------------------------------------------------------------------------------
# Decoding
# ------------------------------------------------------------------------------------------------
def ids_to_tokens(ids, vocab):
    """One output row of token IDs -> tokens, cut at the first <eos> (and never containing <pad>)."""
    eos, pad = vocab["<eos>"], vocab["<pad>"]
    out = []
    for i in ids:
        if i in (eos, pad):
            break
        out.append(vocab.idx_to_token[i])
    return out


# ------------------------------------------------------------------------------------------------
# BLEU
# ------------------------------------------------------------------------------------------------
def ngrams(tokens, n):
    return collections.Counter(tuple(tokens[i:i + n]) for i in range(len(tokens) - n + 1))


def _clip_fn(clip_fn):
    if clip_fn is not None:
        return clip_fn
    if "clipped_matches" not in globals():
        raise RuntimeError("this copy of seq2seq_common has no clipped_matches: pass clip_fn=your clipped_matches")
    return globals()["clipped_matches"]


def corpus_bleu(hyps, refs_list, max_n=4, clip_fn=None):
    """Standard corpus BLEU-4 (x100). hyps: token lists; refs_list: for each hyp, a list of reference token lists.
    clip_fn(hyp, refs, n): the clipped n-gram count (default: this module's clipped_matches)."""
    clip = _clip_fn(clip_fn)
    matches, totals = [0] * max_n, [0] * max_n
    hyp_len = ref_len = 0
    for hyp, refs in zip(hyps, refs_list):
        hyp_len += len(hyp)
        ref_len += min((abs(len(r) - len(hyp)), len(r)) for r in refs)[1]       # closest reference length
        for n in range(1, max_n + 1):
            matches[n - 1] += clip(hyp, refs, n)                                # clipped counts
            totals[n - 1] += max(len(hyp) - n + 1, 0)
    if min(matches) == 0:
        return 0.0
    log_p = sum(math.log(m / t) for m, t in zip(matches, totals)) / max_n
    bp = 1.0 if hyp_len > ref_len else math.exp(1 - ref_len / max(hyp_len, 1))
    return 100 * bp * math.exp(log_p)


