def save_results(path, name, data, hyps, hist=None, extra=None, clip_fn=None, bleu_by_len=None):
    """Write results_hw6.json-style results: BLEU overall and by length, plus every test translation.
    clip_fn: passed to corpus_bleu; bleu_by_len: precomputed {'1-4': BLEU, ...} (else computed here)."""
    if bleu_by_len is None:
        bleu_by_len = bleu_by_length(hyps, data.test_refs, data.test_src, clip_fn=clip_fn)
    res = {
        "model": name,
        "bleu": round(corpus_bleu(hyps, data.test_refs, clip_fn=clip_fn), 2),
        "bleu_by_src_len": {k: round(v, 2) for k, v in bleu_by_len.items()},
        "data": {k: getattr(data, k) for k in ("max_len", "num_train", "num_val", "num_test", "min_freq", "seed")},
        "test_src": [" ".join(s) for s in data.test_src],
        "test_hyp": [" ".join(h) for h in hyps],
    }
    if hist is not None:
        res["train"] = {"steps": hist["steps"], "seconds": round(hist["seconds"], 1),
                        "final_val_loss": round(hist["val_loss"][-1], 4)}
    res.update(extra or {})
    with open(path, "w", encoding="utf-8") as f:
        json.dump(res, f, indent=1, ensure_ascii=False)
    return res


def load_results(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def save_checkpoint(path, model, config, data):
    """Weights (on CPU) + the constructor arguments + both vocabularies, so the model can be rebuilt."""
    torch.save({"state_dict": {k: v.cpu() for k, v in model.state_dict().items()}, "config": config,
                "src_vocab": data.src_vocab.idx_to_token, "tgt_vocab": data.tgt_vocab.idx_to_token}, path)


def load_checkpoint(path, model=None, data=None):
    """Returns the checkpoint dict; if `model` is given, loads the weights into it. If `data` is given,
    checks that its vocabularies are the ones the checkpoint was trained with."""
    ckpt = torch.load(path, map_location="cpu")
    if data is not None:
        assert ckpt["src_vocab"] == data.src_vocab.idx_to_token and ckpt["tgt_vocab"] == data.tgt_vocab.idx_to_token, \
            "the checkpoint was trained with different vocabularies (different data settings?)"
    if model is not None:
        model.load_state_dict(ckpt["state_dict"])
    return ckpt
